<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);$cfg=require $root.'/config.php';date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
try{$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);}catch(Throwable $e){http_response_code(500);exit('No se pudo conectar con MySQL.');}
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$_SESSION['csrf']??=bin2hex(random_bytes(24));
require_once $root.'/app/Core/UnifiedSidebar.php';
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go(string $u):never{header('Location:'.$u);exit;}
function csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Solicitud vencida.');}}
function canManageInventory():bool{if(($_SESSION['user']['role']??'')==='admin')return true;return !empty($_SESSION['user']['permissions']['products']['manage']);}
function ensureStock(PDO $db,int $wid,int $pid,bool $lock=false):array{$sql='SELECT * FROM inventory_stock WHERE warehouse_id=? AND product_id=?'.($lock?' FOR UPDATE':'');$s=$db->prepare($sql);$s->execute([$wid,$pid]);$r=$s->fetch();if(!$r){$db->prepare('INSERT INTO inventory_stock(warehouse_id,product_id,quantity,reserved_quantity,min_quantity) VALUES(?,?,0,0,0)')->execute([$wid,$pid]);$s=$db->prepare($sql);$s->execute([$wid,$pid]);$r=$s->fetch();}return $r;}
function syncTotal(PDO $db,int $pid):void{$s=$db->prepare('SELECT COALESCE(SUM(quantity),0) FROM inventory_stock WHERE product_id=?');$s->execute([$pid]);$db->prepare('UPDATE products SET stock_quantity=? WHERE id=?')->execute([(float)$s->fetchColumn(),$pid]);}
$a=$_GET['a']??'inventory_movements';
$msg=$_SESSION['msg']??null;unset($_SESSION['msg']);
if($a==='save_inventory_movement'){
 try{if(!canManageInventory())throw new Exception('Tu perfil no permite modificar inventario.');csrf();$pid=(int)($_POST['product_id']??0);$wid=(int)($_POST['warehouse_id']??0);$type=(string)($_POST['movement_type']??'');$qty=(float)($_POST['quantity']??0);if(!$pid||!$wid||$qty<0||!in_array($type,['entrada','salida','ajuste'],true))throw new Exception('Revisá producto, depósito, tipo y cantidad.');$db->beginTransaction();$r=ensureStock($db,$wid,$pid,true);$current=(float)$r['quantity'];$reserved=(float)$r['reserved_quantity'];if($type==='ajuste'){$new=$qty;$delta=$new-$current;}else{$delta=$type==='entrada'?abs($qty):-abs($qty);$new=$current+$delta;}if($new<0)throw new Exception('No hay stock suficiente.');if($new-$reserved<0)throw new Exception('La operación afectaría stock reservado.');$db->prepare('UPDATE inventory_stock SET quantity=? WHERE warehouse_id=? AND product_id=?')->execute([$new,$wid,$pid]);
 $cols=$db->query('SHOW COLUMNS FROM inventory_movements')->fetchAll(PDO::FETCH_COLUMN);$data=['product_id'=>$pid,'movement_date'=>date('Y-m-d H:i:s'),'movement_type'=>$type,'quantity'=>$delta,'warehouse_from_id'=>$delta<0?$wid:null,'warehouse_to_id'=>$delta>0?$wid:null,'reference_type'=>'manual','reference'=>trim((string)($_POST['reference']??'')),'notes'=>trim((string)($_POST['notes']??'')),'user_id'=>$_SESSION['user']['id']??null];$use=[];$vals=[];$marks=[];foreach($data as $k=>$v)if(in_array($k,$cols,true)){$use[]=$k;$vals[]=$v;$marks[]='?';}if(!in_array('product_id',$use,true)||!in_array('movement_type',$use,true)||!in_array('quantity',$use,true))throw new Exception('La tabla de movimientos no tiene la estructura necesaria.');$db->prepare('INSERT INTO inventory_movements('.implode(',',$use).') VALUES('.implode(',',$marks).')')->execute($vals);syncTotal($db,$pid);$db->commit();$_SESSION['msg']='Movimiento registrado correctamente.';go('index.php?a=inventory_movements');
 }catch(Throwable $ex){if($db->inTransaction())$db->rollBack();$_SESSION['msg']='No se pudo guardar: '.$ex->getMessage();go('index.php?a=inventory_movements');}
}
try{$products=$db->query("SELECT id,sku,description FROM products WHERE active=1 AND track_stock=1 ORDER BY description")->fetchAll();$warehouses=$db->query("SELECT id,name FROM warehouses WHERE active=1 ORDER BY name")->fetchAll();}catch(Throwable $e){$products=[];$warehouses=[];$msg='Error al cargar productos o depósitos: '.$e->getMessage();}
$recent=[];$historyError=null;try{$recent=$db->query("SELECT m.*,p.sku,p.description FROM inventory_movements m LEFT JOIN products p ON p.id=m.product_id ORDER BY m.id DESC LIMIT 100")->fetchAll();}catch(Throwable $e){$historyError=$e->getMessage();}
$warehouseNames=[];foreach($warehouses as $w)$warehouseNames[(int)$w['id']]=$w['name'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Movimientos · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.c5{grid-column:span 5}.c7{grid-column:span 7px}.c7{grid-column:span 7}.muted{color:var(--muted)}.flash{padding:12px 16px;background:#fff0e5;border:1px solid #ffd2b1;border-radius:9px;margin-bottom:18px}.err{padding:12px 16px;background:#ffecec;border:1px solid #ffcaca;border-radius:9px;margin-bottom:18px}label{display:block;font-weight:650;margin-bottom:6px}input,select,textarea{width:100%;padding:10px 11px;border:1px solid #cbd1d7;border-radius:8px;font:inherit}textarea{min-height:90px}.btn{border:0;border-radius:8px;padding:10px 15px;background:var(--o);color:#fff;font-weight:700;cursor:pointer}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{padding:10px 8px;border-bottom:1px solid var(--line);text-align:left}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.right{text-align:right}.pill{display:inline-block;padding:4px 8px;border-radius:20px;background:#edf0f3;font-size:12px}@media(max-width:900px){.main{margin-left:0;padding:22px 18px}.c5,.c7{grid-column:span 12}}</style></head><body><?php erpSidebar('inventory_movements');?><main class="main"><?php if($msg):?><div class="flash"><?=e($msg)?></div><?php endif;?><h1>Movimientos</h1><p class="muted">Entradas, salidas y ajustes de inventario.</p><?php if($historyError):?><div class="err"><b>No se pudo leer el historial:</b> <?=e($historyError)?><br><small>La pantalla sigue operativa para poder diagnosticar y corregir la estructura.</small></div><?php endif;?><div class="grid"><div class="card c5"><h2>Registrar movimiento</h2><form method="post" action="?a=save_inventory_movement"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><p><label>Producto</label><select name="product_id" required><?php foreach($products as $p):?><option value="<?=$p['id']?>"><?=e($p['sku'].' · '.$p['description'])?></option><?php endforeach;?></select></p><p><label>Depósito</label><select name="warehouse_id" required><?php foreach($warehouses as $w):?><option value="<?=$w['id']?>"><?=e($w['name'])?></option><?php endforeach;?></select></p><p><label>Tipo</label><select name="movement_type"><option value="entrada">Entrada</option><option value="salida">Salida</option><option value="ajuste">Ajuste a cantidad exacta</option></select></p><p><label>Cantidad</label><input type="number" min="0" step=".001" name="quantity" required></p><p><label>Referencia</label><input name="reference" placeholder="Compra, remito, obra, conteo…"></p><p><label>Notas</label><textarea name="notes"></textarea></p><button class="btn">Guardar movimiento</button></form></div><div class="card c7 scroll"><h2>Últimos movimientos</h2><table><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th class="right">Cant.</th><th>Origen / Destino</th><th>Referencia</th></tr><?php if(!$recent):?><tr><td colspan="6" class="muted">Todavía no hay movimientos.</td></tr><?php endif;?><?php foreach($recent as $m):$from=$warehouseNames[(int)($m['warehouse_from_id']??0)]??'—';$to=$warehouseNames[(int)($m['warehouse_to_id']??0)]??'—';?><tr><td><?=e(!empty($m['movement_date'])?date('d/m/Y H:i',strtotime($m['movement_date'])):'—')?></td><td><b><?=e($m['sku']??'Producto eliminado')?></b><br><?=e($m['description']??'')?></td><td><span class="pill"><?=e($m['movement_type']??'—')?></span></td><td class="right"><?=number_format((float)($m['quantity']??0),2,',','.')?></td><td><?=e($from.' → '.$to)?></td><td><?=e($m['reference']??'—')?></td></tr><?php endforeach;?></table></div></div></main></body></html>